cards.content:
{% set blocs = state_attr('sensor.horaires_pro_blocs_gregory', 'blocs') or [] %}
{% if blocs | count == 0 %}
  ℹ️ Aucun bloc Gregory.
{% else %}
  {% for bloc in blocs %}
  **{{ bloc.emoji }} {{ bloc.nom }}**
  — {{ bloc.date[:10] if bloc.date else 'Date non définie' }}
  {% if bloc.start and bloc.end %} · {{ bloc.start }}–{{ bloc.end }}{% endif %}
  {% if bloc.duration_minutes is defined and bloc.duration_minutes > 0 %} · {{ (bloc.duration_minutes / 60) | round(2) }} h{% endif %}

  {% endfor %}
{% endif %}

